import { badRequest, notFound, unprocessableContent } from '@adrianhall/cloudflare-toolkit/errors';
import type { CreateTodoInput, UpdateTodoInput } from './todo';

/**
 * Longest accepted task title. Bounded so a single task cannot be used to store bulk data in the
 * shared `todos` table, and so the UI can render any title without truncation surprises.
 */
const MAX_TITLE_LENGTH = 280;

/**
 * Shape every task identifier must match: a v4-style UUID as generated by `crypto.randomUUID()` in
 * the repository.
 */
export const TODO_ID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/iu;

/**
 * Ensure a parsed JSON value is a plain object suitable for a task payload.
 *
 * Arrays and `null` are rejected explicitly: both are `typeof "object"` in JavaScript, so a naive
 * check would let `[]` or `null` reach property access and produce a confusing `422` instead of a
 * clear `400` about the body's shape.
 *
 * @param value Parsed JSON value from the request body.
 * @returns The same value narrowed to an object with string keys.
 * @throws {ProblemDetailsError} `badRequest()` (400) when the body is not a plain JSON object.
 */
function validateObject(value: unknown): Record<string, unknown> {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    throw badRequest({ detail: 'The request body must be an object.' });
  }
  return value as Record<string, unknown>;
}

/**
 * Normalize a task title and enforce its length bound.
 *
 * @param value Candidate title, straight from the untrusted request body.
 * @returns The trimmed title.
 * @throws {ProblemDetailsError} `unprocessableContent()` (422) when the value is not a string, is
 *   empty or whitespace-only after trimming, or exceeds {@link MAX_TITLE_LENGTH} characters.
 */
function validateTitle(value: unknown): string {
  if (typeof value !== 'string') {
    throw unprocessableContent({ detail: 'title must be a string.' });
  }

  const title = value.trim();
  if (title.length === 0 || title.length > MAX_TITLE_LENGTH) {
    throw unprocessableContent({
      detail: `title must be between 1 and ${MAX_TITLE_LENGTH} characters.`
    });
  }
  return title;
}

/**
 * Validate a create-task request payload.
 *
 * Unknown properties are rejected rather than ignored, so a client that misspells a field finds out
 * immediately instead of silently creating a task without the value it intended to set.
 *
 * @param value Parsed JSON body from the request.
 * @returns Validated creation input.
 * @throws {ProblemDetailsError} `badRequest()` (400) when the body is not an object;
 *   `unprocessableContent()` (422) when a property other than `title` is present, or when `title`
 *   is missing or invalid.
 */
export function validateCreateTodoInput(value: unknown): CreateTodoInput {
  const body = validateObject(value);
  const unexpected = Object.keys(body).filter((key) => key !== 'title');
  if (unexpected.length > 0) {
    throw unprocessableContent({
      detail: `Only title may be supplied; received ${unexpected.join(', ')}.`
    });
  }
  return { title: validateTitle(body.title) };
}

/**
 * Validate a partial task update payload.
 *
 * An empty object is rejected. A request that changes nothing would otherwise still have to load
 * the task to answer, turning the endpoint into an existence oracle for identifiers the caller does
 * not own.
 *
 * @param value Parsed JSON body from the request.
 * @returns The validated mutable fields, with at least one of `title` or `completed` set.
 * @throws {ProblemDetailsError} `badRequest()` (400) when the body is not an object;
 *   `unprocessableContent()` (422) when no mutable field is supplied, an unknown property is
 *   present, `title` is invalid, or `completed` is not a boolean.
 */
export function validateUpdateTodoInput(value: unknown): UpdateTodoInput {
  const body = validateObject(value);
  const keys = Object.keys(body);
  const unexpected = keys.filter((key) => key !== 'title' && key !== 'completed');
  if (keys.length === 0 || unexpected.length > 0) {
    throw unprocessableContent({
      detail: 'Supply title and/or completed, and nothing else.'
    });
  }

  const input: UpdateTodoInput = {};
  if (Object.hasOwn(body, 'title')) {
    input.title = validateTitle(body.title);
  }
  if (Object.hasOwn(body, 'completed')) {
    if (typeof body.completed !== 'boolean') {
      throw unprocessableContent({ detail: 'completed must be a boolean.' });
    }
    input.completed = body.completed;
  }
  return input;
}

/**
 * Validate a task identifier taken from the request path.
 *
 * A malformed identifier raises `notFound()` rather than a validation error on purpose: `404` and
 * "this identifier is not yours" are then indistinguishable to a caller, so neither the response
 * status nor its body reveals whether a well-formed identifier belongs to another user.
 *
 * @param id Candidate task identifier from the URL path.
 * @returns The validated identifier.
 * @throws {ProblemDetailsError} `notFound()` (404) when the identifier is not a UUID.
 */
export function validateTodoId(id: string): string {
  if (!TODO_ID_PATTERN.test(id)) {
    throw notFound({ detail: 'Task not found.' });
  }
  return id;
}
